// Personal and household teaching models. Money is in yuan unless labelled otherwise.
const n=x=>(Math.abs(Number(x))<.005?0:Number(x)).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const money=x=>'¥'+n(x),pct=x=>n(x*100)+'%';
const field=(label,key,value,min=0,max=1e10,unit='元')=>({label,key,value,min,max,unit});
const rate=(label,key,value,min=-100,max=1000)=>field(label,key,value,min,max,'%');
const months=(label,key,value,max=1200)=>field(label,key,value,1,max,'个月');
const lab=(title,fields,run,note,table)=>({title,fields,run,note,table});
const ratio=(a,b)=>b>0?pct(a/b):'分母非正，不适用';
const assetFields=[['活期存款','cash',100000],['定期存款','deposit',200000],['全球股票ETF','etf',300000],['债券基金','bond',150000],['个股','stock',100000],['黄金','gold',50000],['私募基金','private',200000],['自住房产','property',2000000],['汽车','car',150000],['养老金','pension',250000]].map(a=>field(...a));
const debtFields=[['房屋按揭','mortgage',1000000],['汽车贷款','carloan',50000],['信用卡欠款','card',20000],['个人贷款','loan',30000]].map(a=>field(...a));
const flowFields=[field('月税后收入','income',40000),field('必要生活支出（不含还贷）','necessary',12000),field('非必要生活支出','optional',5000),field('月债务偿还（本息）','service',8000)];
export function householdBalance(d){
 const assets=assetFields.reduce((s,f)=>s+d[f.key],0),debt=debtFields.reduce((s,f)=>s+d[f.key],0),outflow=d.necessary+d.optional+d.service,required=d.necessary+d.service,available=d.cash+d.deposit*d.access/100,free=available-required*d.months-d.planned-d.extra;
 return {assets,debt,net:assets-debt,outflow,surplus:d.income-outflow,required,available,free};
}
export function annualCashflow(d){
 if(!Number.isInteger(d.payment)||d.payment<1||d.payment>12)throw Error('付款月份须为1至12的整数。');
 let cash=d.cash,reserve=0;return Array.from({length:12},(_,i)=>{const paid=i+1===d.payment?d.annual:0;cash+=d.income-d.outflow-d.invest-paid;reserve+=d.annual/12-paid;return [i+1,cash,reserve,cash-reserve];});
}
export function incomeStress(d){
 if(!Number.isInteger(d.months))throw Error('收入下降月数须为整数。');if(d.cut>d.outflow)throw Error('压缩支出不能超过原月现金支出。');
 let cash=d.cash;return Array.from({length:12},(_,i)=>{const income=d.income*(i<d.months?1-d.decline/100:1),outflow=d.outflow-d.cut,shock=i===0?d.shock:0;cash+=income-outflow-shock;return [i+1,income,outflow,shock,cash,Math.max(0,-cash)];});
}
export function wealthAccumulation(d){
 const r=d.rate/1200,count=d.years*12;if(!Number.isInteger(count))throw Error('投资期须对应完整月数。');
 const fv=r===0?d.principal+d.contribution*count:d.principal*(1+r)**count+d.contribution*Math.expm1(count*Math.log1p(r))/r;
 return {fv,paid:d.principal+d.contribution*count,real:fv/(1+d.inflation/100)**d.years};
}
export const wealthLabs={
 wealthbalance:lab('个人资产负债表与财务健康', [...assetFields,...debtFields,...flowFields,field('定期存款可动用比例','access',100,0,100,'%'),months('应急储备目标','months',6,120),field('近期额外计划支出','planned',50000),field('额外偿债计划','extra',50000)],d=>{const a=householdBalance(d);return [['总资产',money(a.assets)],['总负债',money(a.debt)],['净资产',money(a.net)],['资产负债率',ratio(a.debt,a.assets)],['净资产比率',ratio(a.net,a.assets)],['月现金结余',money(a.surplus)],['现金储蓄率',ratio(a.surplus,d.income)],['债务偿付比率',ratio(d.service,d.income)],['即时覆盖',a.required>0?n(d.cash/a.required)+'个月':'无必要支出，不适用'],['扩展覆盖',a.required>0?n(a.available/a.required)+'个月':'无必要支出，不适用'],['目标应急资金',money(a.required*d.months)],['可新增投资资金',money(Math.max(0,a.free))],['资金安排缺口',money(Math.max(0,-a.free))],['房地产集中度',ratio(d.property,a.assets)]];},'同币种、同一估值日。可动用存款扣除应急目标、近期支出及额外还债，避免重复扣除。偿还债务前的资产负债表不自动改写。'),
 wealthstress:lab('家庭资产价格与收入双重压力测试',[rate('房产变动','property',-20),rate('股票及ETF变动','equity',-35),rate('债券基金变动','bond',-10),rate('私募基金变动','private',-30),rate('黄金变动','gold',-10),rate('养老金变动','pension',-20),rate('收入下降幅度','decline',50,0,100),months('收入下降持续时间','months',6,120),field('起始活期现金','cash',100000),field('月税后收入','income',40000),field('月总现金支出','outflow',25000)],d=>{if(!Number.isInteger(d.months))throw Error('持续月数须为整数。');const change=(2000000*d.property+400000*d.equity+150000*d.bond+200000*d.private+50000*d.gold+250000*d.pension)/100,assets=3500000+change,surplus=d.income*(1-d.decline/100)-d.outflow,cash=d.cash+surplus*d.months;return [['资产价值变化',money(change)],['压力后总资产',money(assets)],['压力后净资产',money(assets-1100000)],['净资产变动率',pct(change/2400000)],['压力后负债率',ratio(1100000,assets)],['压力期月现金结余',money(surplus)],['压力期末现金',money(cash)],['未融资资金缺口',money(Math.max(0,-cash))]];},'资产价格实验固定采用原课350万元资产、110万元负债；存款、汽车和负债暂不变。收入实验独立计算现金，未并入资产冲击结果；暂停新投资，不计突发支出。'),
 wealthleverage:lab('杠杆风险模拟器',[field('初始资产价值','assets',1000000,.01),rate('借款占资产比例','debt',80,0,99.99),rate('资产价格变动','change',-20)],d=>{const equity=d.assets*(1-d.debt/100),debt=d.assets*d.debt/100,end=d.assets*(1+d.change/100)-debt;return [['初始自有资金',money(equity)],['借款',money(debt)],['权益杠杆',n(d.assets/equity)+'倍'],['期末净资产',money(end)],['自有资金收益率',pct(end/equity-1)]];},'静态代数模型，借款本金不变，未计利息、税费、追加保证金与追索条款；负权益不自动等于实际追索金额。'),
 wealthreal:lab('真实财富与购买力',[field('当前净资产','principal',1000000),rate('名义财富年增长率','rate',0,-99,100),rate('年通胀率','inflation',3,-99,100),field('年数','years',10,1,100,'年')],d=>{const nominal=d.principal*(1+d.rate/100)**d.years;return [['未来名义财富',money(nominal)],['按今天购买力折算',money(nominal/(1+d.inflation/100)**d.years)],['真实年增长率',pct((1+d.rate/100)/(1+d.inflation/100)-1)]];},'固定增长率和通胀假设，不计新增储蓄、提取、税费及波动。'),
 wealthfx:lab('跨境资产与汇率风险',[field('英镑资产','amount',100000,0,1e10,'英镑'),field('初始GBP/CNY汇率','start',9.2,.0001,100000,'人民币/英镑'),field('期末GBP/CNY汇率','end',8.5,.0001,100000,'人民币/英镑'),rate('英镑资产自身回报','return',0)],d=>{const initial=d.amount*d.start,final=d.amount*(1+d.return/100)*d.end;return [['初始人民币价值',money(initial)],['期末人民币价值',money(final)],['人民币损益',money(final-initial)],['人民币回报',initial>0?pct(final/initial-1):'初始金额为零，不适用']];},'汇率为教学假设。总回报＝(1＋本币资产回报)×(期末汇率/初始汇率)－1；未计税费与换汇点差。'),
 wealthspending:lab('持续消费成本',[field('每日消费','daily',30),field('每年消费天数','days',365,0,366,'天'),field('持续年数','years',10,1,100,'年')],d=>[['年度消费',money(d.daily*d.days)],['月均消费',money(d.daily*d.days/12)],['累计消费',money(d.daily*d.days*d.years)]],'不计通胀和机会成本。用于识别支出，不代表所有小额消费都应取消。'),
 wealthbudget:lab('家庭预算比例',[field('月税后收入','income',40000),rate('必要支出比例','needs',50,0,100),rate('可选消费比例','wants',30,0,100)],d=>{if(d.needs+d.wants>100)throw Error('必要支出与可选消费比例之和不能超过100%。');const saving=1-(d.needs+d.wants)/100;return [['必要支出',money(d.income*d.needs/100)],['可选消费',money(d.income*d.wants/100)],['财务目标拨款',money(d.income*saving)],['年度财务目标拨款',money(d.income*saving*12)]];},'最低合同还款计入必要支出，额外还债可计入财务目标。50/30/20是参考框架，可以修改比例。'),
 wealthcashflow:lab('零基预算与全年储蓄',[...flowFields,field('月还贷本金（已含于本息）','principal',5000),field('年度额外支出','annual',50000),field('月长期投资拨款','invest',10000)],d=>{if(d.principal>d.service)throw Error('还贷本金不能超过还贷本息。');const regular=d.income-d.necessary-d.optional-d.service,annual=regular*12-d.annual;return [['常规月结余',money(regular)],['常规现金储蓄率',ratio(regular,d.income)],['债务偿付比率',ratio(d.service,d.income)],['专项月拨款',money(d.annual/12)],['调整后月均结余',money(annual/12)],['年度计划现金结余',money(annual)],['年度计划储蓄率',ratio(annual,d.income*12)],['月未分配结余',money(annual/12-d.invest)],['年度广义储蓄率',ratio(annual+d.principal*12,d.income*12)]];},'投资购买不算消费，年度专项支出只扣一次。专项拨款保留完整精度；广义储蓄加回还贷本金。'),
 wealthsinking:lab('专项储蓄目标',[field('目标金额','target',50000),field('已有专项资金','saved',0),months('剩余期限','months',12)],d=>[['尚需积累',money(Math.max(0,d.target-d.saved))],['每月拨款',money(Math.max(0,d.target-d.saved)/d.months)]],'等额月度拨款，已达标时拨款为零。提前到期的目标须按实际期限计算，不计利息。'),
 wealthannual:lab('12个月家庭现金流预测',[field('期初活期现金','cash',100000),field('月税后收入','income',40000),field('月常规现金支出','outflow',25000),field('月长期投资','invest',10000),field('年度额外支出','annual',50000),field('额外支出付款月','payment',12,1,12,'月')],d=>{const rows=annualCashflow(d),min=Math.min(d.cash,...rows.map(r=>r[1]));return [['年度税后收入',money(d.income*12)],['年度非投资现金支出',money(d.outflow*12+d.annual)],['年度投资拨款',money(d.invest*12)],['年末现金',money(rows.at(-1)[1])],['最低资金余额',money(min)],['最大未融资缺口',money(Math.max(0,-min))]];},'投资拨款是现金转为投资资产。专项每月内部预留不减少家庭总现金，实际付款时才扣现金；提前付款可使专项账户余额为负，表示预存不足。',d=>({headers:['月份','期末现金（元）','专项余额（元）','未指定现金（元）'],rows:annualCashflow(d).map(r=>r.map((v,i)=>i?n(v):String(v)))})),
 wealthvariance:lab('预算差异分析',[field('预算收入','budgetIncome',40000),field('实际收入','actualIncome',40000),field('预算必要支出','budgetNeeds',12000),field('实际必要支出','actualNeeds',12500),field('预算非必要支出','budgetWants',5000),field('实际非必要支出','actualWants',5800),field('预算偿债','budgetDebt',8000),field('实际偿债','actualDebt',8000),field('专项月拨款','sinking',50000/12),field('长期月投资','invest',10000)],d=>{const b=d.budgetIncome-d.budgetNeeds-d.budgetWants-d.budgetDebt,a=d.actualIncome-d.actualNeeds-d.actualWants-d.actualDebt;return [['预算月结余',money(b)],['实际月结余',money(a)],['结余有利差异',money(a-b)],['必要支出有利差异',money(d.budgetNeeds-d.actualNeeds)],['非必要支出有利差异',money(d.budgetWants-d.actualWants)],['实际储蓄率',ratio(a,d.actualIncome)],['维持原拨款后的余缺',money(a-d.sinking-d.invest)]];},'收入有利差异＝实际－预算，支出有利差异＝预算－实际；正数有利。'),
 wealthaccumulation:lab('长期储蓄与投资积累',[field('初始本金','principal',0),field('月末投入','contribution',10000),field('投资年数','years',20,1,100,'年'),rate('假设名义年收益率','rate',6,-99,100),rate('假设年通胀率','inflation',3,-99,100)],d=>{const a=wealthAccumulation(d);return [['模拟期末资产',money(a.fv)],['累计投入本金',money(a.paid)],['假设投资损益',money(a.fv-a.paid)],['按今天购买力折算',money(a.real)]];},'名义年收益率除以12、每月月末投入。收益率为零时终值＝本金＋月投入×月数；真实市场收益不固定，不计税费。'),
 wealthcost:lab('未来家庭生活成本',[field('当前月生活支出（不含债务）','living',17000),field('固定月还贷','debt',8000),rate('生活成本年增长率','inflation',3,-99,100),field('预测年数','years',10,1,100,'年')],d=>{const current=d.living+d.debt,future=d.living*(1+d.inflation/100)**d.years+d.debt;return [['当前月现金支出',money(current)],['未来月现金支出',money(future)],['每月新增需求',money(future-current)]];},'仅生活支出随通胀增长，债务月偿还额假设固定且持续整个预测期。'),
 wealthincomestress:lab('家庭收入中断压力测试',[field('期初现金','cash',100000),field('正常月税后收入','income',40000),field('原月现金支出','outflow',25000),rate('收入下降幅度','decline',50,0,100),months('收入下降月数','months',6,12),field('首月突发支出','shock',20000),field('每月压缩支出','cut',0)],d=>{const rows=incomeStress(d),min=Math.min(d.cash,...rows.map(r=>r[4]));return [['压力期月收入',money(d.income*(1-d.decline/100))],['压力期月结余',money(d.income*(1-d.decline/100)-d.outflow+d.cut)],['压力期末资金余额',money(rows[d.months-1][4])],['全年最低资金余额',money(min)],['全年最大资金缺口',money(Math.max(0,-min))],['第12个月资金余额',money(rows.at(-1)[4])]];},'暂停新投资，不计原年度专项支出。压力期后收入恢复，压缩支出延续至年末。负余额表示尚未融资的资金缺口。',d=>({headers:['月份','收入（元）','常规支出（元）','突发支出（元）','资金余额（元）','缺口（元）'],rows:incomeStress(d).map(r=>r.map((v,i)=>i?n(v):String(v)))}))
};
